() => {
  const [isIndeterminate, setIsIndeterminate] = useState(true)
  return (
    <form>
      <FormControl>
        <Checkbox
          value="default"
          indeterminate={isIndeterminate}
          onChange={() => {
            setIsIndeterminate(!isIndeterminate)
          }}
          checked={false}
        />
        <FormControl.Label>Default label</FormControl.Label>
      </FormControl>
    </form>
  )
}
